//! The identifier of a snapshot (NGSI-LD clause 5.2.41).

uri_identifier!(
    /// The identifier of a snapshot: a URI (NGSI-LD clause 5.2.41), chosen by the client or generated by the broker
    /// when the snapshot is created or cloned without one (clauses 5.16.1.4 and 5.16.2.4). It names the snapshot an
    /// operation is aimed at in the `NGSILD-Snapshot` header (clause 6.3.22).
    ///
    /// ```
    /// use iri_rs::iri;
    /// use ngsi_ld::snapshot::SnapshotId;
    ///
    /// let id = SnapshotId::from(iri!("urn:ngsi-ld:Snapshot:1"));
    /// assert_eq!(id, "urn:ngsi-ld:Snapshot:1".parse::<SnapshotId>()?);
    /// # Ok::<(), anyhow::Error>(())
    /// ```
    SnapshotId
);
